import{a as r}from"./chunk-XQSQEGUZ.js";import{a,b as t}from"./chunk-BKXKKHFA.js";var n=[{slug:"heavy-haulage",heading:"Heavy haulage across *Australia*",metaTitle:"Heavy Haulage Transport Australia | FreightMove",metaDescription:"Get quotes for oversize and overmass heavy haulage anywhere in Australia. Float and low loader operators who run OSOM work every week, compared side by side.",intro:"Anything too tall, too wide or too heavy for a standard trailer becomes a permit job, an escort job, or both. The carriers who do this work daily already hold the accreditations and know which routes their load will actually fit down.",moves:["Excavators, dozers and graders","Cranes and drill rigs","Transformers and industrial plant","Prefabricated steel and precast concrete","Mining and agricultural equipment","Anything over 2.5m wide or 4.3m high"],equipment:[{name:"Float / low loader",note:"Deck height drops to carry tall plant under bridges."},{name:"Drop deck",note:"A step in the deck buys extra height for machinery."},{name:"Extendable trailer",note:"Stretches for long single items such as blades or beams."},{name:"Platform / jinker",note:"Multi-axle combinations for concentrated heavy weight."}],considerations:[{title:"Permits and escorts",body:"Oversize or overmass loads run under NHVR permits, and above certain dimensions need pilot or police escorts. That is time and cost before a wheel turns, and it is why an OSOM quote is rarely comparable to a general freight one."},{title:"Route survey",body:"Bridges, overhead lines, roundabouts and level crossings decide the route more than distance does. Experienced operators price the route they can actually run, not the one a map suggests."},{title:"Access at both ends",body:"Getting a float into a paddock or a tight yard is often the hardest part of the job. Tell carriers about surface, slope and turning space up front and the quotes come back realistic."}],faqs:[{q:"What counts as an oversize load in Australia?",a:"Broadly, anything wider than 2.5m, higher than 4.3m, or longer than 19m as a combination \u2014 and overmass once axle limits are exceeded. Exact thresholds vary by state and by the permit or notice the operator runs under."},{q:"Do I need to arrange the permits?",a:"No. The carrier holds the permits and arranges escorts, because they are issued against that operator, that vehicle and that route. Their quote should say whether permit and escort costs are included."},{q:"How far ahead should I book heavy haulage?",a:"Further than general freight. Permits take time to issue and escorts have to be scheduled, so a week or more is sensible for a large OSOM movement."},{q:"Can you move machinery that does not run?",a:"Yes, though it changes the equipment. A non-runner needs winching onto the deck rather than driving on, so say so when you post the load \u2014 it affects both the trailer and the price."}],related:["machinery-transport","truck-trailer-transport","container-transport"]},{slug:"general-freight",heading:"General freight, *anywhere in Australia*",metaTitle:"General Freight Transport Australia | FreightMove",metaDescription:"Compare quotes for general freight across Australia \u2014 cartons, pallets, crates and commercial goods, metro to remote, from carriers already running your lane.",intro:"The everyday freight that keeps businesses running: cartons, crates, pallets and packaged goods moving between depots, sites and customers. The cheapest way to move it is almost always on a truck already heading that way.",moves:["Palletised and cartoned goods","Retail and wholesale stock","Trade supplies and hardware","Furniture and fit-out materials","Packaged manufactured goods","Part loads and full loads"],equipment:[{name:"Curtainsider",note:"Side access for forklift loading at either end."},{name:"Pantech / van body",note:"Fully enclosed, weatherproof, common for metro work."},{name:"Flat tray",note:"Simple and versatile where the load can be strapped and tarped."},{name:"B-double",note:"Highest volume per trip on the main interstate corridors."}],considerations:[{title:"Full load or part load",body:"A part load shares the truck and the cost, and usually costs less. A full load goes direct and arrives sooner. Which is better depends on whether the date or the price matters more to you."},{title:"How it is packaged",body:"Freight on pallets, shrink-wrapped and labelled, moves faster and cheaper than loose items. Every carrier prices the handling as well as the kilometres."},{title:"Loading and unloading",body:"A forklift or dock at both ends keeps the job simple. If either end is hand unload or needs a tailgate lift, say so up front so the quotes reflect it."}],faqs:[{q:"What is the difference between general freight and palletised freight?",a:"Palletised freight is general freight already on pallets, which makes it quicker to handle and easier to price. General freight also covers crates, cartons and irregular items that need more thought."},{q:"Can I send freight to a residential address?",a:"Yes, but say so when posting. Residential deliveries often need a tailgate lift and a booked time window, and a carrier who only quotes depot-to-depot will price it differently."},{q:"How is general freight priced?",a:"Mostly by distance and the space it takes \u2014 either weight or cubic volume, whichever is greater. Access, timing and whether it fills a truck or shares one do the rest."},{q:"Do you move freight to regional areas?",a:"Yes. Regional and remote work is normal in Australian freight; it usually runs on a schedule rather than daily, so allow a little more time."}],related:["palletised-freight","container-transport","truck-trailer-transport"]},{slug:"container-transport",heading:"Container transport and *wharf cartage*",metaTitle:"Container Transport Australia | Wharf Cartage | FreightMove",metaDescription:"Quotes for 20ft and 40ft container transport across Australia \u2014 wharf cartage, side loaders and skel trailers, from operators who work the ports daily.",intro:"Containers move on specific equipment and to port timetables. Whether it is a wharf collection under a timeslot or a shed sitting in a yard, the right trailer decides whether it can be dropped where you want it.",moves:["20ft and 40ft shipping containers","High cube and open top containers","Refrigerated containers (reefers)","Empty container repositioning","Storage and site containers","Import and export wharf cartage"],equipment:[{name:"Side loader",note:"Self-loading \u2014 lifts the container off and places it on the ground."},{name:"Skel trailer",note:"Purpose-built container chassis; needs a crane or forklift at the site."},{name:"Flat top",note:"Works where there is machinery on site to lift the box."},{name:"Tilt tray",note:"Suits smaller boxes and awkward site access."}],considerations:[{title:"Can it be self-loaded?",body:"A side loader places the container on the ground without a crane, which is the difference between a simple delivery and hiring lifting gear. It is the single most useful thing to tell a carrier."},{title:"Wharf timeslots and detention",body:"Port collections run to booked windows, and time waiting beyond the free period is chargeable. Operators who run wharf work daily price this realistically rather than discovering it later."},{title:"Weight and where it sits",body:"A loaded 20ft can be heavier than a loaded 40ft. Give the carrier the actual gross weight \u2014 it determines the axle configuration and whether the run is legal."}],faqs:[{q:"Can a container be delivered to a site with no forklift or crane?",a:"Yes, on a side loader. It lifts the container off its own trailer and sets it down. You need enough clear length and reasonably level ground alongside the truck."},{q:"Do you collect containers straight from the wharf?",a:"Yes \u2014 wharf cartage is standard container work. The carrier books the timeslot and handles the port paperwork."},{q:"What ground do I need for a side loader delivery?",a:"Firm and reasonably level, with room for the truck plus roughly the container length again. Soft ground or a slope is where deliveries go wrong, so mention it in advance."},{q:"Can you move a container with goods still inside?",a:"Usually yes, if it is loaded and restrained properly and within weight limits. Tell the carrier the gross weight, since a loaded box changes the equipment needed."}],related:["general-freight","heavy-haulage","portable-building-transport"]},{slug:"machinery-transport",heading:"Machinery transport for *plant and equipment*",metaTitle:"Machinery Transport Australia | Plant Movers | FreightMove",metaDescription:"Move excavators, tractors, forklifts and industrial plant anywhere in Australia. Compare quotes from float and drop deck operators who move machinery every week.",intro:"Machinery is not just heavy \u2014 it is awkward, valuable and often has to be driven, winched or craned onto the deck. The operators who do it routinely already own the tie-down gear and know how to load it without damage.",moves:["Excavators, skid steers and loaders","Tractors and harvesters","Forklifts and telehandlers","Compressors, generators and pumps","Workshop and factory plant","Scissor lifts and boom lifts"],equipment:[{name:"Drop deck",note:"Lower deck height for tall machines, with ramps to drive on."},{name:"Float / low loader",note:"For the heavy end \u2014 tracked plant and large machines."},{name:"Tilt tray",note:"Tilts to ground level; ideal for smaller machines and non-runners."},{name:"Flat top with ramps",note:"Straightforward for machines that drive on under their own power."}],considerations:[{title:"Dimensions and weight, honestly",body:"Machine weight from the spec sheet is often the bare unit. Attachments, buckets, counterweights, a full fuel tank and mud all add up, and the difference can push a load into permit territory."},{title:"Does it drive on?",body:"A running machine can be driven up ramps. A seized or damaged one needs winching or lifting, which changes the equipment and the price. Say which up front."},{title:"Tracks, tyres and decks",body:"Steel tracks damage decks and roads, so they may need pads or a specific trailer. Mention track type when posting \u2014 it is a common cause of a quote changing on the day."}],faqs:[{q:"Do I need to remove attachments before transport?",a:"Often yes. Buckets, booms and counterweights add height and width, and removing them can keep a load inside legal dimensions \u2014 turning a permit job into an ordinary one."},{q:"Is the machinery insured while it is on the truck?",a:"Carriers hold goods-in-transit and liability cover, but limits and exclusions vary. Ask the carrier what their cover actually is for the value of your machine before you book."},{q:"Who loads the machine?",a:"Usually the carrier, since restraint is their legal responsibility under chain-of-responsibility rules. If you are driving it on, they will still direct the load and secure it."},{q:"Can you move machinery to a mine or remote site?",a:"Yes. Remote and site work is common, though site inductions and access requirements are worth mentioning early because they affect scheduling."}],related:["heavy-haulage","truck-trailer-transport","bulk-tipper-transport"]},{slug:"livestock-transport",heading:"Livestock transport with *welfare first*",metaTitle:"Livestock Transport Australia | Cattle & Sheep | FreightMove",metaDescription:"Compare quotes for cattle, sheep and livestock transport across Australia from accredited operators running crates, decks and road trains.",intro:"Moving animals is a welfare responsibility as much as a freight job. Accredited livestock operators run purpose-built crates, know the curfew and rest rules, and carry the paperwork that has to travel with the stock.",moves:["Cattle \u2014 station, feedlot and saleyard movements","Sheep and lambs","Pigs and goats","Horses and stud stock","Saleyard and abattoir deliveries","Station to station transfers"],equipment:[{name:"Single deck crate",note:"For cattle and larger stock; sheeted for weather."},{name:"Double deck crate",note:"Sheep and smaller stock, more head per trip."},{name:"B-double stock crate",note:"Long-haul volume on the main corridors."},{name:"Road train",note:"Multiple trailers for remote and station work."}],considerations:[{title:"Curfew and time off water",body:"Stock are curfewed before loading and there are limits on time off water, which shape the whole schedule. An experienced operator plans the run around them rather than around the odometer."},{title:"Paperwork travels with the stock",body:"NVDs and waybills must accompany the movement, and the operator will ask for them. Having them ready is the difference between loading on time and holding the truck up."},{title:"Loading facilities",body:"Ramp height, race condition and yard layout decide how smoothly loading goes and how long it takes. Tell the carrier what you have; it affects both time and stress on the animals."}],faqs:[{q:"Are livestock carriers accredited?",a:"Reputable operators work to the land transport standards for livestock welfare and are commonly TruckSafe or similar accredited. Ask \u2014 and on FreightMove, a carrier's verification status is shown against their quote."},{q:"How is livestock transport priced?",a:"Usually by the deck or by head over distance, rather than by weight alone. Remote pickups, curfew timing and waiting at yards all factor in."},{q:"What happens if an animal is injured in transit?",a:"Operators carry insurance and are required to manage welfare en route, including stopping if needed. Agree beforehand what the carrier's cover is for the stock you are moving."},{q:"Can you do saleyard pickups?",a:"Yes \u2014 saleyard and abattoir work is routine for livestock carriers, and they will work to the yard's own timetable."}],related:["grain-hay-transport","truck-trailer-transport","general-freight"]},{slug:"boat-transport",heading:"Boat and yacht transport *by road*",metaTitle:"Boat Transport Australia | Yacht Transport | FreightMove",metaDescription:"Move boats, yachts and marine craft anywhere in Australia. Compare quotes from operators experienced in cradles, wide loads and marina access.",intro:"A boat on a truck is a high-value, wide, top-heavy load. The operators who move them regularly bring proper cradles and know which marinas and ramps a semi can actually get into.",moves:["Runabouts and trailer boats","Yachts and keel boats","Catamarans and multihulls","Commercial and charter vessels","Marina and boatyard relocations","New boat deliveries from dealers"],equipment:[{name:"Flat top with cradle",note:"Purpose-made cradles support the hull without stressing it."},{name:"Drop deck",note:"Lower deck keeps tall craft under height limits."},{name:"Extendable trailer",note:"For long hulls that overhang a standard deck."},{name:"Tilt tray",note:"Smaller boats, and where ramp access is tight."}],considerations:[{title:"Height is usually the problem",body:"Hull on a cradle plus deck height is what has to clear every bridge on the route. Superstructure, masts and radar arches often have to come off, and that is a job to plan rather than discover on the day."},{title:"Masts and rigging",body:"Yacht masts are almost always unstepped and travel separately or alongside. Arrange it with the marina before the truck arrives \u2014 a crane booking is not something a driver can improvise."},{title:"Access at the water",body:"Marinas, ramps and hardstands vary enormously in what size vehicle they can take. Confirm the access, the lifting arrangements and who is craning at each end."}],faqs:[{q:"Do I need a cradle for my boat?",a:"For anything without its own road trailer, yes. The cradle spreads the hull's weight properly; strapping a hull straight to a deck is how gelcoat and structural damage happens."},{q:"Can you transport a boat still on its trailer?",a:"Often yes, and it is usually cheaper \u2014 the boat and trailer travel together on a flat top or tilt tray. The trailer needs to be roadworthy enough to be loaded and restrained."},{q:"Does the mast have to come down?",a:"For a yacht, nearly always. A stepped mast puts the load far over height limits. Most marinas can unstep it, and it travels lashed alongside the hull."},{q:"How much does it cost to transport a boat interstate?",a:"It depends on hull length, beam, height once cradled, and whether the load is oversize. Beam over 2.5m makes it a wide load with permit and possibly escort costs, which is the biggest single factor."}],related:["heavy-haulage","machinery-transport","container-transport"]},{slug:"truck-trailer-transport",heading:"Truck and trailer *relocation*",metaTitle:"Truck & Trailer Transport Australia | FreightMove",metaDescription:"Relocate trucks, prime movers, trailers and buses across Australia. Compare quotes from operators who tow, piggyback and float commercial vehicles.",intro:"Moving a commercial vehicle that cannot or should not be driven \u2014 unregistered, sold interstate, or off the road. There is usually more than one way to do it, and they price very differently.",moves:["Prime movers and rigid trucks","Semi and dog trailers","Buses and coaches","Unregistered and non-running vehicles","Dealer and auction deliveries","Fleet relocations"],equipment:[{name:"Tilt tray",note:"Winches a non-runner on without needing it to drive."},{name:"Float / low loader",note:"For heavy or tall units that must be carried, not towed."},{name:"Towing / piggyback",note:"Often the cheapest option when the unit is roadworthy enough."},{name:"Extendable trailer",note:"For long trailers and buses that overhang."}],considerations:[{title:"Driven, towed or carried",body:"A registered roadworthy truck can simply be driven or towed, which is far cheaper than carrying it on a float. An unregistered or non-running unit has to be carried. That single fact moves the price more than distance does."},{title:"Registration status",body:"Unregistered vehicles cannot be towed on public roads without an unregistered vehicle permit. Tell the carrier the status up front so they quote the legal method."},{title:"Keys, air and brakes",body:"A unit that can be rolled, steered and braked is far easier to load. Seized brakes or missing keys mean winching and sometimes extra equipment."}],faqs:[{q:"Can you move an unregistered truck?",a:"Yes. It is either carried on a float or tilt tray, or towed under an unregistered vehicle permit. Which one is cheaper depends on the distance and the vehicle's condition."},{q:"Is it cheaper to have my truck driven instead?",a:"Sometimes, if it is registered, roadworthy and insured. Against that, you add wear, fuel and kilometres to the vehicle. For long interstate moves carrying it often works out comparable."},{q:"Can you transport a trailer separately from the prime mover?",a:"Yes. Trailers are commonly towed on their own by an operator with the right coupling, or carried if unregistered."},{q:"What about a truck that will not start?",a:"A tilt tray or float with a winch handles it. Mention whether it rolls and steers \u2014 that decides how straightforward loading will be."}],related:["machinery-transport","heavy-haulage","general-freight"]},{slug:"grain-hay-transport",heading:"Grain and hay *cartage*",metaTitle:"Grain & Hay Transport Australia | Farm Cartage | FreightMove",metaDescription:"Compare quotes for grain, hay and fodder cartage across Australia \u2014 tippers, chaser bins, flat tops and road trains, from operators who run harvest every season.",intro:"Seasonal, weather-dependent and time-critical. Grain and hay carriers work to harvest and receival-site hours, and the good ones are booked before the header starts.",moves:["Wheat, barley, canola and pulses","Hay bales \u2014 round and square","Silage and fodder","Farm to silo and receival site","On-farm and paddock to paddock","Stockfeed deliveries"],equipment:[{name:"Tipper",note:"Bulk grain, tipping at the silo or receival site."},{name:"B-double tipper",note:"High volume per trip on the main grain corridors."},{name:"Flat top",note:"Baled hay, strapped and tarped."},{name:"Road train",note:"Remote and high-volume seasonal cartage."}],considerations:[{title:"Harvest timing",body:"Everyone needs a truck in the same fortnight. Booking early is the difference between carting on schedule and watching grain sit. Rain closes paddocks with little notice, so build in some flexibility."},{title:"Receival site hours",body:"Silos and receival sites have their own opening times and queues. A carrier who runs that region already knows them and plans loads around them."},{title:"Cleanliness and contamination",body:"Bins carrying certified or segregated grain must be clean and free of residues. If your load has segregation requirements, say so before booking, not on arrival."}],faqs:[{q:"How is grain cartage priced?",a:"Usually per tonne over distance, sometimes per load for short farm runs. Waiting time at receival sites and paddock access affect the final number."},{q:"Can you cart hay interstate?",a:"Yes. Baled hay travels on flat tops and B-doubles. Height and width matter once bales are stacked, so a load can become oversize more easily than people expect."},{q:"Do carriers supply tarps?",a:"Yes, carters running grain and hay carry tarps and straps as standard, and tarping is part of restraining the load legally."},{q:"Can trucks get into the paddock?",a:"It depends on surface, recent rain and turning space \u2014 a B-double needs a lot of room. Describe the access when posting so quotes are based on reality."}],related:["bulk-tipper-transport","livestock-transport","general-freight"]},{slug:"bulk-tipper-transport",heading:"Bulk tipper *haulage*",metaTitle:"Bulk Tipper Transport Australia | Sand & Gravel | FreightMove",metaDescription:"Quotes for bulk tipper haulage across Australia \u2014 sand, soil, gravel, aggregate and quarry products, from operators running tippers and side tippers daily.",intro:"Loose material moved by the tonne, usually to a site with a deadline. What matters is tipping room, turnaround time and whether the truck can get in and out without getting bogged.",moves:["Sand, soil and fill","Gravel, road base and aggregate","Quarry and crushed products","Mulch, compost and landscape supplies","Demolition and excavation spoil","Mine site and civil works material"],equipment:[{name:"Rigid tipper",note:"Smaller loads and tight urban sites."},{name:"Semi tipper",note:"The workhorse for civil and quarry cartage."},{name:"Side tipper",note:"Tips sideways where there is no room to raise a body."},{name:"Truck and dog",note:"More payload per trip while staying manoeuvrable."}],considerations:[{title:"Room to tip",body:"A raised tipper body is very tall and needs firm level ground and clear overhead space. Powerlines and low branches are the usual obstacles, and a side tipper is the answer where height is impossible."},{title:"Getting in and out",body:"Loaded tippers are heavy and bog easily. Soft ground, steep entries and wet weather change what can be delivered, and how much per load."},{title:"Weight limits, not volume",body:"Bulk material is priced and limited by tonnes, and density varies a lot \u2014 wet sand is far heavier than mulch. Give the material type so the carrier can work out the legal payload."}],faqs:[{q:"How much can a tipper carry?",a:"Roughly 8 to 12 tonnes for a rigid, and around 25 to 30 tonnes for a semi tipper, depending on configuration and the material. The legal limit is on axle mass, so a dense material fills the weight before it fills the body."},{q:"Can a tipper deliver to a residential driveway?",a:"Often yes with a smaller rigid truck, but it needs firm ground, clear overhead space and room to raise the body. A tight suburban site may need a smaller truck and more trips."},{q:"What if the site is wet?",a:"Loaded tippers bog readily and getting one out is expensive. Most operators will assess it on arrival, and a wet site is a common reason a delivery is rescheduled."},{q:"Do you cart contaminated or classified spoil?",a:"Some operators do, but it needs the right licensing and an approved disposal destination. Say so when posting the job so only carriers set up for it quote."}],related:["grain-hay-transport","machinery-transport","heavy-haulage"]},{slug:"liquid-tanker-transport",heading:"Liquid tanker *transport*",metaTitle:"Liquid Tanker Transport Australia | Bulk Liquids | FreightMove",metaDescription:"Compare quotes for bulk liquid transport across Australia \u2014 water, fuel, chemicals and food-grade liquids, from licensed tanker operators.",intro:"Bulk liquid is specialised work. The tanker has to suit the product, the operator has to be licensed for it if it is dangerous goods, and food-grade work brings cleaning requirements of its own.",moves:["Potable and non-potable water","Diesel, fuel and oils","Industrial chemicals","Food-grade liquids and milk","Liquid fertiliser","Waste and effluent"],equipment:[{name:"Water tanker",note:"Potable-rated tanks for drinking water cartage."},{name:"Fuel tanker",note:"Compartmented, with pumps and metering."},{name:"Chemical tanker",note:"Lined or stainless tanks matched to the product."},{name:"Food-grade tanker",note:"Cleaned and certified between loads."}],considerations:[{title:"Dangerous goods licensing",body:"Fuels and many chemicals are dangerous goods under the ADG code. The driver needs the licence, the vehicle needs the placarding and the operator needs the right insurance. Name the product when posting \u2014 it decides who can legally quote."},{title:"The tank must suit the product",body:"Tankers are not interchangeable. A tank that has carried chemicals cannot carry drinking water, and food-grade work requires documented cleaning between loads."},{title:"Pumping and connections",body:"How the liquid gets in and out matters as much as the cartage. Confirm whether the truck needs its own pump, what fittings are at each end, and how far the hose has to reach."}],faqs:[{q:"Can you cart drinking water?",a:"Yes, with a potable-rated tanker that carries only potable water. Do not accept a general tanker for drinking water, whatever the price."},{q:"Do I need a dangerous goods licensed carrier?",a:"If the product is classified under the ADG code \u2014 most fuels, many chemicals \u2014 then yes, and the operator must be licensed and the load placarded. State the product and its class when you post the job."},{q:"How much does a tanker hold?",a:"Commonly around 15,000 to 30,000 litres depending on configuration, though the legal limit is mass rather than volume, so a dense liquid fills the weight before the tank."},{q:"Who supplies the hoses and fittings?",a:"Usually the carrier, but fittings are not universal. Confirm the connection type at both ends before the truck is dispatched."}],related:["bulk-tipper-transport","general-freight","container-transport"]},{slug:"portable-building-transport",heading:"Portable building *transport*",metaTitle:"Portable Building Transport Australia | FreightMove",metaDescription:"Move site sheds, cabins, granny flats and modular buildings across Australia. Compare quotes from operators experienced in wide loads and crane-assisted delivery.",intro:"Transportable buildings are wide, tall and fragile in the wrong hands. Almost every one is an oversize load, and getting it onto its final position usually needs more than a truck.",moves:["Site sheds and site offices","Portable cabins and dongas","Granny flats and studios","Modular and prefabricated homes","Ablution and amenity blocks","Classrooms and demountables"],equipment:[{name:"Drop deck",note:"Lower deck keeps overall height within limits."},{name:"Extendable trailer",note:"For long buildings that overhang a standard deck."},{name:"Tilt tray",note:"Smaller cabins where site access is tight."},{name:"Widening trailer",note:"Supports the full footprint of a wide building."}],considerations:[{title:"It is almost certainly oversize",body:"Most transportable buildings exceed 2.5m wide once on a deck, which means permits and often escorts. Give exact width, length and height \u2014 including the roof \u2014 because a small difference changes the permit category."},{title:"Craning on and off",body:"Buildings usually need lifting rather than driving on. A crane or extendable forks at each end has to be arranged and timed with the truck; an idle crane is expensive."},{title:"Final placement",body:"Getting the building to the property is one job; getting it onto piers or a slab at the back of a block is another. Be clear about the final position when you post it."}],faqs:[{q:"Do I need council approval to move a building?",a:"Transport itself runs under road permits, but siting a transportable building usually needs council or planning approval at the destination. That is separate from the cartage and worth sorting first."},{q:"How wide can a transportable building be?",a:"Buildings well over 5m wide are moved regularly, but each width step adds permit conditions, escorts and route restrictions. Width is the main cost driver."},{q:"Can the building be placed on site, not just delivered?",a:"Placement generally needs a crane or specialised lifting gear. Some operators arrange it, others deliver only \u2014 confirm which when comparing quotes."},{q:"Will the building be damaged in transit?",a:"Experienced operators brace and strap buildings to travel. Older or poorly built structures can flex on the road, so it is worth discussing condition before booking."}],related:["heavy-haulage","container-transport","machinery-transport"]},{slug:"palletised-freight",heading:"Palletised freight, *simply moved*",metaTitle:"Palletised Freight Transport Australia | FreightMove",metaDescription:"Send pallets anywhere in Australia. Compare quotes for one pallet or a full truckload from carriers already running your lane.",intro:"The most straightforward freight there is: standardised, easy to handle and quick to price. One pallet or thirty-four, the question is simply whose truck is already going your way.",moves:["Standard and Chep pallets","Oversized and non-standard pallets","Shrink-wrapped and strapped loads","Single pallets and part loads","Full truckloads","Depot to depot and door to door"],equipment:[{name:"Curtainsider",note:"Side loading, the standard for palletised work."},{name:"Pantech with tailgate",note:"Enclosed, and can unload where there is no forklift."},{name:"B-double",note:"Up to 34 pallets per trip on interstate runs."},{name:"Rigid truck",note:"Smaller runs and metro delivery."}],considerations:[{title:"Pallet size and stacking",body:"Standard and Chep pallets fit predictably; anything overhanging takes more space than it looks and is priced accordingly. Whether pallets can be double-stacked makes a real difference to cost."},{title:"Forklift at both ends",body:"A forklift or dock keeps a pallet delivery quick and cheap. Without one, the truck needs a tailgate lift \u2014 available, but say so up front."},{title:"Wrap and label",body:"Shrink-wrapped, strapped and clearly labelled pallets survive handling and transfers. Loose or poorly wrapped loads are where damage claims come from."}],faqs:[{q:"How many pallets fit on a truck?",a:"Roughly 22 on a standard semi trailer and up to 34 on a B-double, single-stacked. A rigid truck carries considerably fewer, depending on body length."},{q:"Can I send a single pallet?",a:"Yes. A single pallet travels as part of a shared load, which is why it costs far less than hiring a whole truck."},{q:"What if there is no forklift at delivery?",a:"Ask for a tailgate lift when posting. The driver lowers the pallet to ground level hydraulically. It is a common requirement and worth stating up front rather than at the door."},{q:"How should pallets be prepared?",a:"Stacked squarely within the pallet footprint, shrink-wrapped, strapped if heavy, and labelled. Nothing overhanging \u2014 overhang gets damaged and takes up paid space."}],related:["general-freight","container-transport","truck-trailer-transport"]}],i=new Map(r.map(e=>[e.slug,e])),s=n.map(e=>t(a({},e),{card:i.get(e.slug)}));function h(e){return s.find(o=>o.slug===e)}var c={"heavy-carriers":"heavy-haulage","truck-transport":"truck-trailer-transport","trailer-transport":"truck-trailer-transport","grain-transport":"grain-hay-transport","hay-transport":"grain-hay-transport","portable-buildings-transport":"portable-building-transport"};export{s as a,h as b,c};
